"use strict";(function(){"use strict";document.querySelectorAll('.banner-banner[data-dismissible="true"]').forEach(n=>{const e=n.dataset.bannerId;e&&localStorage.getItem("banner-dismissed-"+e)&&(n.style.display="none")}),window.SnakkActions.on("dismiss-banner",n=>{const e=n.dataset.bannerId;e&&localStorage.setItem("banner-dismissed-"+e,"1");const s=n.closest(".banner-banner");s&&(s.style.display="none")})})();
